-- STRICTLY READ ONLY: run after 202608280001 is manually applied.
with checks(check_name,status,details,blocking) as (
 values
 ('TABLES_EXIST',case when to_regclass('public.oil_supplier_bills') is not null and to_regclass('public.oil_supplier_payments') is not null and to_regclass('public.oil_supplier_payment_allocations') is not null then 'PASS' else 'FAIL' end,'All three supplier accounting tables',true),
 ('PAYMENT_RPC',case when to_regprocedure('public.save_oil_supplier_payment(bigint,uuid,date,numeric,numeric,text,text,text)') is not null and to_regprocedure('public.delete_oil_supplier_payment(bigint)') is not null then 'PASS' else 'FAIL' end,'Exact save/delete RPC signatures',true),
 ('REBUILD_RPC_SECURITY',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.rebuild_oil_supplier_accounting(uuid)') and p.prosecdef and array_to_string(p.proconfig,',') like '%search_path=public, pg_temp%') then 'PASS' else 'FAIL' end,'Rebuild is SECURITY DEFINER with locked search_path',true),
 ('RLS_ENABLED',case when not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in('oil_supplier_bills','oil_supplier_payments','oil_supplier_payment_allocations') and not c.relrowsecurity) then 'PASS' else 'FAIL' end,'RLS enabled on all accounting tables',true),
 ('DIRECT_MUTATION_BLOCKED',case when not has_table_privilege('authenticated','public.oil_supplier_bills','INSERT') and not has_table_privilege('authenticated','public.oil_supplier_payments','INSERT') and not has_table_privilege('authenticated','public.oil_supplier_payment_allocations','INSERT') then 'PASS' else 'FAIL' end,'Authenticated direct writes blocked',true),
 ('AUTHENTICATED_RPC_ONLY',case when has_function_privilege('authenticated','public.save_oil_supplier_payment(bigint,uuid,date,numeric,numeric,text,text,text)','EXECUTE') and not has_function_privilege('anon','public.save_oil_supplier_payment(bigint,uuid,date,numeric,numeric,text,text,text)','EXECUTE') then 'PASS' else 'FAIL' end,'Authenticated execute; anon blocked',true),
 ('SOURCE_BILL_TRIGGERS',case when exists(select 1 from pg_trigger where tgrelid='public.oil_purchases'::regclass and tgname='oil_purchases_supplier_bill' and not tgisinternal) and exists(select 1 from pg_trigger where tgrelid='public.oil_vehicle_entries'::regclass and tgname='oil_vehicle_entries_supplier_bill' and not tgisinternal) then 'PASS' else 'FAIL' end,'Both authoritative source triggers exist',true),
 ('CASHBOOK_UNIQUENESS',case when to_regclass('public.cashbook_entries_oil_supplier_reference_uidx') is not null then 'PASS' else 'FAIL' end,'Automatic Oil supplier reference unique index',true),
 ('CASHBOOK_PROTECTION',case when exists(select 1 from pg_trigger where tgrelid='public.cashbook_entries'::regclass and tgname='cashbook_entries_protect_oil_supplier' and not tgisinternal) then 'PASS' else 'FAIL' end,'Oil supplier automatic Cashbook protection trigger',true),
 ('SOURCE_COVERAGE',case when (select count(*) from public.oil_supplier_bills where source_type='oil_purchase')=(select count(*) from public.oil_purchases where total_amount>0) and (select count(*) from public.oil_supplier_bills where source_type='oil_vehicle_entry')=(select count(*) from public.oil_vehicle_entries where source_type='external_shop' and total_amount>0) then 'PASS' else 'FAIL' end,'Every eligible authoritative source has exactly one bill',true),
 ('NO_ADDA_STOCK_LIABILITY',case when not exists(select 1 from public.oil_supplier_bills b join public.oil_vehicle_entries e on e.id=b.oil_vehicle_entry_id where e.source_type='adda_stock') then 'PASS' else 'FAIL' end,'Adda-stock issues never create supplier liability',true),
 ('NO_ORPHANS',case when not exists(select 1 from public.oil_supplier_bills b left join public.oil_shops s on s.id=b.oil_shop_id where s.id is null) and not exists(select 1 from public.oil_supplier_payment_allocations a left join public.oil_supplier_payments p on p.id=a.payment_id left join public.oil_supplier_bills b on b.id=a.supplier_bill_id where p.id is null or b.id is null) then 'PASS' else 'FAIL' end,'No orphan accounting rows',true),
 ('NO_DUPLICATE_CASHBOOK',case when not exists(select 1 from public.cashbook_entries where reference_type='oil_supplier_payment' group by reference_id having count(*)>1) then 'PASS' else 'FAIL' end,'No duplicate payment_now Cashbook rows',true),
 ('COUNTS','INFO',(select format('%s bills; %s payments; %s allocations; %s payment Cashbook rows',(select count(*) from public.oil_supplier_bills),(select count(*) from public.oil_supplier_payments),(select count(*) from public.oil_supplier_payment_allocations),(select count(*) from public.cashbook_entries where reference_type='oil_supplier_payment'))),false)
), combined as (
 select 'OVERALL_OIL_SUPPLIER_ACCOUNTING_POST_VERIFY'::text check_name,case when count(*) filter(where blocking and status='FAIL')=0 then 'PASS' else 'FAIL' end status,format('%s blocking check(s) failed; %s passed; %s informational',count(*) filter(where blocking and status='FAIL'),count(*) filter(where status='PASS'),count(*) filter(where status='INFO')) details from checks
 union all select check_name,status,details from checks
)
select check_name,status,details from combined order by case when check_name='OVERALL_OIL_SUPPLIER_ACCOUNTING_POST_VERIFY' then 0 else 1 end,check_name;
